PAGES=[]
PAGES.append(P(slug='youtube-channel-terminated-how-to-get-it-back',svc='yt',crumb=CR,navrel=NAV,
 title='YouTube Channel Terminated? How to Get It Back (2026 Guide)',short='Get a terminated channel back',
 desc='Your YouTube channel was terminated. How the termination appeal works, what to write, what to avoid, and when to get help. Unbanz: $1,200 upfront, 100% refund if it fails.',
 h1='How to get a terminated YouTube channel back.',lede='The order to work in after a YouTube channel termination, from the email to the appeal form.',
 answer='<strong>Appeal the termination through the form linked in YouTube’s termination email or from the Channel or account terminations help page.</strong> Sign in with the Google Account that owned the channel, explain briefly why the decision is wrong, and submit once. Do not create or use other channels while terminated; YouTube treats that as circumvention. If the appeal is rejected, Unbanz handles YouTube channel terminations for $1,200, paid upfront, with a 100% refund if it fails.',
 cards=[('One appeal','YouTube reviews one termination appeal.'),('No new channels','Using other channels counts as circumvention.'),('Read the email','It names the policy and the form.')],
 sections=[('steps','Step by step',ol(['Find the termination email and screenshot it, including the policy named.','Sign in to the owning Google Account and open the termination appeal form from the email or the help page below.','Write a short, specific explanation: what the channel is, why you believe the policy was misapplied, and what you will change if anything.','Submit once and wait for the reply by email.','If rejected, decide whether to escalate with a stronger case.'])),
 ('reasons','Most common termination reasons',ul(['Three Community Guidelines strikes within 90 days.','Three copyright strikes.','A single case of severe abuse, such as spam, scams or harmful content.','A channel linked to another terminated channel.','A channel taken over by hackers and used for scams.'])),
 ('links','Official links',L('term','strikes','cr','standing'))],
 faqs=[('How long does a YouTube termination appeal take?','Often days, sometimes weeks. YouTube replies by email.'),('Can a terminated YouTube channel be restored?','Yes, when the appeal succeeds. Channels terminated by mistake or after a hack are the best candidates.'),('How much does Unbanz charge for YouTube?','$1,200 per channel, paid upfront by card, with a 100% refund if it fails. Usually 3–7 days, not guaranteed.'),('Do you need my Google password?','No. We never ask for passwords or codes.')],
 related=[('/youtube-channel-terminated-appeal-links-directory/','YouTube appeal links'),('/youtube-termination-appeal-what-to-write/','What to write in the appeal')],
 howto=('How to appeal a YouTube channel termination',['Screenshot the termination email.','Open the appeal form while signed in to the owning account.','Explain briefly why the decision is wrong.','Submit once.','Wait for YouTube’s email reply.'])))
PAGES.append(P(slug='youtube-termination-appeal-what-to-write',svc='yt',crumb=CR,navrel=NAV,
 title='YouTube Termination Appeal: What to Write (With Examples)',short='YouTube appeal what to write',
 desc='How to write a YouTube channel termination appeal that gets read: structure, example wording for spam, copyright and linked-channel terminations, and mistakes to avoid.',
 h1='What to write in a YouTube termination appeal.',lede='The appeal form has limited space. Use it well.',
 answer='<strong>A strong YouTube termination appeal names the channel, states the policy from the email, explains in two or three sentences why it does not fit, and shows what kind of content the channel actually makes.</strong> Be specific and calm. Do not paste long legal text or threaten YouTube.',
 cards=[('Name the policy','Use the wording from the email.'),('Show the channel','What you publish and for how long.'),('Be specific','Dates, video titles if relevant.')],
 sections=[('structure','Structure',ol(['Channel name and URL.','The policy YouTube named.','Why it does not apply, in plain words.','What the channel is for and how long it has run.','A polite request to reinstate.'])),
 ('examples','Example wording',ul(['<em>Spam, deceptive practices and scams:</em> “My channel publishes original cooking tutorials since 2019. I do not run giveaways or link to external offers. I believe the spam policy was applied by mistake, possibly after a hack attempt on [date].”','<em>Linked channel:</em> “The terminated channel you linked to mine is not mine; we share a household network. My channel has no strikes.”','<em>Hacked:</em> “My channel was hijacked on [date] and used to stream crypto scams. I have recovered and secured the Google Account.”'])),
 ('avoid','Avoid',ul(['Copy-paste templates from forums.','Arguing about other channels that “do worse”.','Promising things you cannot keep.']))],
 faqs=[('Is there a character limit?','The form is short, so keep it focused.'),('Can I appeal again after a rejection?','Usually not through the same form. See what to do after a rejected appeal.')],
 related=[('/youtube-appeal-rejected-what-next/','Appeal rejected'),('/youtube-channel-terminated-how-to-get-it-back/','Get a terminated channel back')]))
